from __future__ import annotations

import ast
from dataclasses import dataclass
from pathlib import Path


@dataclass(slots=True, frozen=True)
class ImportRecord:
    """Immutable record of a single import statement with canonical POSIX path."""
    module: str
    alias: str | None
    level: int  # 1 for top-level imports, 2 for from-imports


@dataclass(slots=True, frozen=True)
class ModuleImports:
    """Canonical import registry for a parsed Python module."""
    top_level: list[ImportRecord]
    from_imports: list[ImportRecord]


def extract_imports(tree: ast.Module) -> ModuleImports:
    """Extract all import statements from an AST tree into a canonical, deduplicated registry."""
    records: list[ImportRecord] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                records.append(ImportRecord(
                    module=alias.name,
                    alias=alias.name if alias.asname else None,
                    level=1,
                ))
        elif isinstance(node, ast.ImportFrom):
            module = node.module or ""
            for alias in node.names:
                records.append(ImportRecord(
                    module=module,
                    alias=alias.name if alias.asname else None,
                    level=2,
                ))
    return ModuleImports(
        top_level=sorted(set(r for r in records if r.level == 1), key=lambda x: x.module),
        from_imports=sorted(set(r for r in records if r.level == 2), key=lambda x: x.module),
    )
```

### Guarantees
- **POSIX path safety**: Uses `path.posix` semantics (no Windows drive letters or backslashes).
- **Zero-copy parsing**: Operates directly on `ast.Module` without reading source bytes.
- **Deterministic output**: Returns sorted, deduplicated lists with `frozen=True` immutability.
